WITH enriched AS (SELECT *, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY ends_on, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS discount_pct_avg_6, AVG(discount_pct) OVER (PARTITION BY channel ORDER BY ends_on, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_5_prior FROM promotions) SELECT id, channel, promo_code, ends_on, discount_pct, discount_pct_avg_6, discount_pct_avg_5_prior FROM enriched ORDER BY discount_pct_avg_5_prior DESC;
